/* eslint-disable no-template-curly-in-string */ //${...}は通常JSの変数や式を展開するためにテンプレートリテラル(`〜`)内で使用するが
//今回はYupのプレースホルダーとして使用するため文字列('〜')として記述、ESLintの警告を出さないために上記の一文は記述するもの、先頭に記述することでファイル全体に適応

import * as yup from 'yup';

const safeTransform = transformFunction => value => (typeof value === 'string' ? transformFunction(value) : value);
//safeTransformは関数を受け取って関数を返す高階関数、transformFunctionの部分で文字列を加工する関数を受け取る、
//valueが文字列以外だった場合も安全に変換できるようにする、Yupの.transform()でnullやundefinedを渡されても落ちない

const schema = yup.object({
  name: yup
    .string()
    .label('名前')
    .transform(safeTransform (value => value//.transform()は入力された値をバリデーション前に変換する、変換後の値をバリデーションに渡すという役割
        .normalize('NFKC')//Unicode正規化、英数字などを全角→半角、カナを半角→全角などの正規化
        .replace(/\s+/g, ' ')//\s(全角・半角スペースや改行)+(1回以上の繰り返し)g(全ての一致箇所を取得)、連続スペースを1個にする、姓 名の見栄えの安定のために設定
        .trim()//文字列の先頭と末尾の余分なスペースを削除する(ExcelのTRIM関数とは異なりJSのtrim()は文字列内の連続する空白を削除しない)
    ))
    .required('${label}は入力必須です')
    .max(20, '${label}は${max}文字以内で入力してください'),
  email: yup
    .string()
    .label('メールアドレス')
    .transform(safeTransform (value =>value
        .normalize('NFKC')
        .trim()
        .toLowerCase()//小文字に統一
    ))
    .required('${label}は入力必須です')
    .email('${label}の形式が不正です'),
  title: yup
    .string()
    .label('件名')
    .transform(safeTransform (value => value
        .normalize('NFKC')
        .trim()
    ))
    .required('${label}は入力必須です')
    .max(50, '${label}は${max}文字以内で入力してください。'),
  message: yup
    .string()
    .label('本文')
    .transform(safeTransform (value => {//綺麗な文字列にしてから次のバリデーションに渡す
      const normalized = value.normalize('NFKC')
        .replace(/\r\n?/g, '\n')//改行コードの統一を行う、\r→CR(キャリッジリターン)、Windowsや古いMacの改行コードに含まれる、カーソルを文頭へ戻す役割、
        //\n→LF(ラインフィード)、改行の役割、正規表現における?は直前の文字やグループが0回または1回現れることを示す量指定子、\r\n(Windowsの改行(CRLF))、\r(古いMacの改行(CR))をLFに統一
        //複数のOSで作成された文章を扱うと改行コードが混在すること有、その場合改行がうまく反映されなかったり文字化けの原因になること有、
        //一旦全ての改行コードをLFに統一すればプログラムが予測通りに動き改行処理が安定する
        .replace(/[ \t]+$/gm, '');//各行末の空白を削除する、[ \t]→半角スペース( )またはタブ文字(\t)が1回以上連続、//$→行末(文字列全体ではなく1行ごとの末尾)、
        //m→複数行モード、通常モードでは^は文字列の先頭に、$は文字列の末尾にのみマッチするが、複数行モード(m)だと^は各行の先頭に、$は各行の末尾にマッチする
      return normalized;
    }))
    .test('not-blank', '${label}は入力必須です。', value => !!value && value.trim().length > 0)//Yupの.test()は独自の検証ルールを追加するための関数、
    //test(name, message, testFunction)
    //name: ルールの識別子、message: バリデーションエラー時に表示するメッセージ、testFunction: 実際のチェック処理(trueを返せばOK、falseならエラー)
    .required('${label}は入力必須です。')//.required()は空白だけの入力を未入力とは判定しない場合有、空白しか入力されていないケースを明示的に除外するためにtestを追加
    .min(10, '${label}は${min}文字以上で入力してください。'),
  agreement: yup
    .boolean()
    .oneOf([true], 'プライバシーポリシーに同意してください'),//値が配列[true]の中に含まれているかどうかを確認、trueであることを条件にしているのでチェックボックスがONの場合のみ通る
});

export default schema;
